IF DB_ID('OpinionesExterno') IS NULL CREATE DATABASE OpinionesExterno;
GO
USE OpinionesExterno;
GO
IF OBJECT_ID('dbo.Resenas','U') IS NOT NULL DROP TABLE dbo.Resenas;
GO
CREATE TABLE dbo.Resenas (
    ResenaID     INT IDENTITY(1,1) PRIMARY KEY,
    Cliente      VARCHAR(100) NOT NULL,
    Correo       VARCHAR(150) NULL,
    Producto     VARCHAR(100) NOT NULL,
    Plataforma   VARCHAR(50)  NOT NULL,
    Calificacion INT          NOT NULL,
    Texto        VARCHAR(1000) NULL,
    FechaResena  DATE         NOT NULL
);
GO
GO
SELECT COUNT(*) AS TotalResenas FROM dbo.Resenas;
GO
